///////////////////////////////////////////////////
// CDDA: Pocket PPAD stack (Paprium) + Pezz mdp_audio (other MD+)
///////////////////////////////////////////////////

localparam CDDA_CHUNK      = 4096;
localparam CDDA_CHUNKS     = 2; // M10K reclaim: half IMA ring (was 4)
// S2: the paprium.pcm DDR blob is gone (music is streamed from the SD slot-1 image). The FS3 OSD loader below is
// compiled out (ENABLE_FS3_DDR_LOAD=0); its nominal base is moved out of Linux RAM (was 0x1000_0000) so it could never write there.
localparam [31:0] PAPRIUM_PCM_BASE = 32'h3800_0000;
localparam        ENABLE_FS3_DDR_LOAD = 0;

wire signed [15:0] mdp_cdda_l, mdp_cdda_r;
wire signed [15:0] pcm_cdda_l, pcm_cdda_r;
wire signed [15:0] cdda_l = paprium_active ? pcm_cdda_l : mdp_cdda_l;
wire signed [15:0] cdda_r = paprium_active ? pcm_cdda_r : mdp_cdda_r;
wire        [15:0] cdda_underruns;
wire               pcm_blob_ok;

// --- Pezz HPS-fed PCM ring (non-Paprium MD+) ---
// M10K reclaim: gate off for Paprium-only core (mdp_audio FIFO ~8Kb M10K).
localparam ENABLE_MDP_AUDIO = 0;
wire  [7:0] mdp_DDRAM_BURSTCNT;
wire [28:0] mdp_DDRAM_ADDR;
wire        mdp_DDRAM_RD;
wire [63:0] mdp_DDRAM_DIN;
wire  [7:0] mdp_DDRAM_BE;
wire        mdp_DDRAM_WE;

generate
if (ENABLE_MDP_AUDIO) begin : mdp_on
mdp_audio mdp_audio
(
	.clk(clk_sys),
	.reset(sys_reset | paprium_active),

	.DDRAM_CLK(),
	.DDRAM_BUSY(DDRAM_BUSY),
	.DDRAM_BURSTCNT(mdp_DDRAM_BURSTCNT),
	.DDRAM_ADDR(mdp_DDRAM_ADDR),
	.DDRAM_DOUT(DDRAM_DOUT),
	.DDRAM_DOUT_READY(DDRAM_DOUT_READY),
	.DDRAM_RD(mdp_DDRAM_RD),
	.DDRAM_DIN(mdp_DDRAM_DIN),
	.DDRAM_BE(mdp_DDRAM_BE),
	.DDRAM_WE(mdp_DDRAM_WE),

	.active(mdp_audio_active & ~paprium_active),
	.buf_wr_ptr(mdp_audio_wr_ptr),
	.buf_rd_ptr(mdp_audio_rd_ptr),

	.track_start(mdplus_mdp_track_request),
	.stop_request(mdplus_mdp_stop_request),
	.fade_sectors(mdplus_mdp_fade_sectors),
	.volume(mdplus_mdp_volume),
	.resume_request(mdplus_mdp_resume_request),
	.osd_pause(OSD_STATUS & status[61]),
	.rate_48k(1'b0),

	.audio_l(mdp_cdda_l),
	.audio_r(mdp_cdda_r)
);
end else begin : mdp_off
	assign mdp_cdda_l = 16'sd0;
	assign mdp_cdda_r = 16'sd0;
	assign mdp_DDRAM_BURSTCNT = 8'd0;
	assign mdp_DDRAM_ADDR = 29'd0;
	assign mdp_DDRAM_RD = 1'b0;
	assign mdp_DDRAM_DIN = 64'd0;
	assign mdp_DDRAM_BE = 8'd0;
	assign mdp_DDRAM_WE = 1'b0;
	assign mdp_audio_rd_ptr = 16'd0;
end
endgenerate

