wire  [7:0] load_DDRAM_BURSTCNT;
wire [28:0] load_DDRAM_ADDR;
wire        load_DDRAM_RD;
wire [63:0] load_DDRAM_DIN;
wire  [7:0] load_DDRAM_BE;
wire        load_DDRAM_WE;
wire        pcm_loading;

generate
if (ENABLE_FS3_DDR_LOAD) begin : pcm_load_on
paprium_pcm_load #(.BLOB_BASE_BYTE(PAPRIUM_PCM_BASE)) paprium_pcm_load
(
	.clk(clk_sys),
	.reset(sys_reset),
	.download(pcm_download),
	.ioctl_wr(ioctl_wr),
	.ioctl_addr(ioctl_addr),
	.ioctl_data(ioctl_data),
	.ioctl_wait(pcm_ioctl_wait),
	.DDRAM_CLK(),
	.DDRAM_BUSY(DDRAM_BUSY),
	.DDRAM_BURSTCNT(load_DDRAM_BURSTCNT),
	.DDRAM_ADDR(load_DDRAM_ADDR),
	.DDRAM_DOUT(DDRAM_DOUT),
	.DDRAM_DOUT_READY(DDRAM_DOUT_READY),
	.DDRAM_RD(load_DDRAM_RD),
	.DDRAM_DIN(load_DDRAM_DIN),
	.DDRAM_BE(load_DDRAM_BE),
	.DDRAM_WE(load_DDRAM_WE),
	.loading(pcm_loading),
	.bytes_written()
);
end else begin : pcm_load_off
	assign pcm_ioctl_wait     = 1'b0;
	assign pcm_loading        = 1'b0;
	assign load_DDRAM_BURSTCNT= 8'd0;
	assign load_DDRAM_ADDR    = 29'd0;
	assign load_DDRAM_RD      = 1'b0;
	assign load_DDRAM_DIN     = 64'd0;
	assign load_DDRAM_BE      = 8'd0;
	assign load_DDRAM_WE      = 1'b0;
end
endgenerate

// --- Pocket CDDA stack (fetch / buf / ima / play) ---

wire        cdda_buf_wr_en;
wire [12:0] cdda_buf_wr_addr;
wire [15:0] cdda_buf_wr_data;
wire  [2:0] cdda_wr_chunk_gray, cdda_rd_chunk_gray;
wire [12:0] cdda_rd_ptr;
wire [31:0] cdda_rd_data;
wire [12:0] cdda_fill;
wire        cdda_consumed;

// S2: pcm image mounted by Main on hps_io slot 1 (img_mounted[1]); size latched here at its own mount,
// because img_size is one register shared with the save slot.
reg  [31:0] pcm_size_lo = 0;
reg         pcm_size_hi = 0;
reg         pcm_present = 0;
reg         pcm_old_mnt = 0;
reg         pcm_mount_ev = 0;
always @(posedge clk_sys) begin
	pcm_old_mnt  <= img_mounted[1];
	pcm_mount_ev <= img_mounted[1] & ~pcm_old_mnt;
	if(img_mounted[1] & ~pcm_old_mnt) begin
		pcm_size_lo <= img_size[31:0];
		pcm_size_hi <= |img_size[63:32];
		pcm_present <= |img_size;
	end
end

paprium_cdda_fetch #(
	.CHUNK_BYTES(CDDA_CHUNK),
	.NUM_CHUNKS (CDDA_CHUNKS)
) paprium_cdda_fetch (
	.clk(clk_sys),
	.reset(sys_reset | ~paprium_active | pcm_download),

	.track_request(ppm_mdp_track_request),
	.track_num    (ppm_mdp_track_num),
	.track_loop   (ppm_mdp_track_loop),
	.stop_request (ppm_mdp_stop_request),

	.pcm_mount_ev (pcm_mount_ev),
	.pcm_present  (pcm_present),
	.pcm_size_lo  (pcm_size_lo),
	.pcm_size_hi  (pcm_size_hi),

	.sd_lba       (pcm_sd_lba),
	.sd_blk_cnt   (pcm_sd_blk_cnt),
	.sd_rd        (pcm_sd_rd),
	.sd_ack       (sd_ack[1]),
	.sd_buff_addr (sd_buff_addr[11:0]),
	.sd_buff_dout (sd_buff_dout),
	.sd_buff_wr   (sd_buff_wr),

	.buf_wr_en  (cdda_buf_wr_en),
	.buf_wr_addr(cdda_buf_wr_addr),
	.buf_wr_data(cdda_buf_wr_data),

	.rd_chunk_gray(cdda_rd_chunk_gray),
	.wr_chunk_gray(cdda_wr_chunk_gray),

	.playing      (mdp_pcm_playing),
	.current_track(mdp_pcm_current_track),
	.blob_ok      (pcm_blob_ok),

	.underruns    (cdda_underruns),
	.info_req     (pcm_info_req),
	.info         (pcm_info)
);

// S2: stretch the ring flush after a track request. The fetch side clears its chunk counter on a
// track request and the ring side sees that through a 3-stage synchroniser; with the old counter
// still visible the decoder would eat stale ring bytes (and, once the counter reads 0 again with a
// non-zero in-chunk offset, keep eating them until the first SD chunk lands). Holding the ring-side
// flush for 24 clocks keeps the read side at zero until the cleared counter has propagated.
reg  [4:0] cdda_flush_cnt = 0;
always @(posedge clk_sys) begin
	if (ppm_mdp_track_request) cdda_flush_cnt <= 5'd24;
	else if (cdda_flush_cnt != 0) cdda_flush_cnt <= cdda_flush_cnt - 1'd1;
end
wire cdda_flush = ppm_mdp_track_request | (cdda_flush_cnt != 0);

paprium_cdda_buf #(
	.CHUNK_BYTES(CDDA_CHUNK),
	.NUM_CHUNKS (CDDA_CHUNKS)
) paprium_cdda_buf (
	.clk(clk_sys),
	.reset(sys_reset | ~paprium_active),

	.wr_en  (cdda_buf_wr_en),
	.wr_addr(cdda_buf_wr_addr),
	.wr_data(cdda_buf_wr_data),

	.wr_chunk_gray(cdda_wr_chunk_gray),
	.rd_chunk_gray(cdda_rd_chunk_gray),

	.rd_ptr         (cdda_rd_ptr),
	.rd_data        (cdda_rd_data),
	.sample_consumed(cdda_consumed),
	.fill_level     (cdda_fill),

	.flush(cdda_flush)
);

paprium_cdda_play #(
	.RING_SAMPLES(CDDA_CHUNK * CDDA_CHUNKS / 4)
) paprium_cdda_play (
	.clk(clk_sys),
	.reset(sys_reset | ~paprium_active),

	.active        (ppm_mdp_active),
	.track_start   (ppm_mdp_track_request),
	.stop_request  (ppm_mdp_stop_request),
	.fade_sectors  (ppm_mdp_fade_sectors),
	.volume        (ppm_mdp_volume),
	.resume_request(ppm_mdp_resume_request),
	.osd_pause     (OSD_STATUS & status[61]),

	.rd_ptr         (cdda_rd_ptr),
	.rd_data        (cdda_rd_data),
	.fill_level     (cdda_fill),
	.sample_consumed(cdda_consumed),

	.underruns(cdda_underruns),
	.audio_l  (pcm_cdda_l),
	.audio_r  (pcm_cdda_r)
);

