/////////////////////////  BRAM SAVE/LOAD  /////////////////////////////

wire downloading = cart_download;

reg bk_ena = 0;
reg sav_pending = 0;
wire bk_change;

always @(posedge clk_sys) begin
	reg old_downloading = 0;
	reg old_change = 0;

	old_downloading <= downloading;
	if(~old_downloading & downloading) bk_ena <= 0;

	//Save file always mounted in the end of downloading state.
	if(downloading && img_mounted[0] && !img_readonly) bk_ena <= 1;

	old_change <= bk_change;
	if (~old_change & bk_change & ~OSD_STATUS) sav_pending <= 1;
	else if (bk_state) sav_pending <= 0;
end

// S2: img_size is one register shared by both slots; remember the SAVE image size at its own mount
reg save_img_present = 0;
always @(posedge clk_sys) if(img_mounted[0]) save_img_present <= |img_size;

wire bk_load    = status[16] | status[100]; // RESET1: OSD "Hard reset" (R[100]) reuses the Load Backup RAM request
wire bk_save    = status[17] | (sav_pending & OSD_STATUS);
reg  bk_loading = 0;
reg  bk_state   = 0;

always @(posedge clk_sys) begin
	reg old_downloading = 0;
	reg old_load = 0, old_save = 0, old_ack;

	old_downloading <= downloading;

	old_load <= bk_load;
	old_save <= bk_save;
	old_ack  <= sd_ack[0];

	if(~old_ack & sd_ack[0]) {sd_rd, sd_wr} <= 0;

	if(!bk_state) begin
		if(bk_ena & ((~old_load & bk_load) | (~old_save & bk_save))) begin
			bk_state <= 1;
			bk_loading <= bk_load;
			sd_lba <= 0;
			sd_rd <=  bk_load;
			sd_wr <= ~bk_load;
		end
		if(old_downloading & ~downloading & save_img_present & bk_ena) begin
			bk_state <= 1;
			bk_loading <= 1;
			sd_lba <= 0;
			sd_rd <= 1;
			sd_wr <= 0;
		end
	end else begin
		if(old_ack & ~sd_ack[0]) begin
			if(&sd_lba[6:0]) begin
				bk_loading <= 0;
				bk_state <= 0;
			end else begin
				sd_lba <= sd_lba + 1'd1;
				sd_rd  <=  bk_loading;
				sd_wr  <= ~bk_loading;
			end
		end
	end
end


///////////////////////////////////////////////////
// Cheat codes loading for WIDE IO (16 bit)
`ifdef M68K_CHEAT
`define MD_ANY_CHEAT
`endif
`ifdef Z80_CHEAT
`define MD_ANY_CHEAT
`endif

`ifdef MD_ANY_CHEAT
reg [128:0] gg_code;
`endif
`ifdef M68K_CHEAT
wire        gg_available;
`else
wire        gg_available = 1'b0;
`endif

`ifdef MD_ANY_CHEAT
// Code layout:
// {clock bit, code flags,     32'b address, 32'b compare, 32'b replace}
//  128        127:96          95:64         63:32         31:0
// Integer values are in BIG endian byte order, so it up to the loader
// or generator of the code to re-arrange them correctly.

always_ff @(posedge clk_sys) begin
	gg_code[128] <= 1'b0;

	if (code_download & ioctl_wr) begin
		case (ioctl_addr[3:0])
			0:  gg_code[111:96]  <= ioctl_data; // Flags Bottom Word
			2:  gg_code[127:112] <= ioctl_data; // Flags Top Word
			4:  gg_code[79:64]   <= ioctl_data; // Address Bottom Word
			6:  gg_code[95:80]   <= ioctl_data; // Address Top Word
			8:  gg_code[47:32]   <= ioctl_data; // Compare Bottom Word
			10: gg_code[63:48]   <= ioctl_data; // Compare top Word
			12: gg_code[15:0]    <= ioctl_data; // Replace Bottom Word
			14: begin
				gg_code[31:16]   <= ioctl_data; // Replace Top Word
				gg_code[128]     <=  1'b1;      // Clock it in
			end
		endcase
	end
end
`endif

`ifdef M68K_CHEAT
	reg [15:0] m68k_data;
	always @(posedge clk_md) m68k_data <= m68k_genie_data;

	wire [15:0] m68k_genie_data;
	CODES #(.ADDR_WIDTH(24), .DATA_WIDTH(16), .BIG_ENDIAN(1)) codes_68k
	(
		.clk(clk_sys),
		.reset(cart_download | (code_download && ioctl_wr && !ioctl_addr)),
		.enable(~status[24]), // FXSMS1: was ~status[24] & ~cart_ms
		.code(gg_code),
		.available(gg_available),
		.addr_in({m68k_addr, 1'b0}),
		.data_in(m68k_bus_do),
		.data_out(m68k_genie_data)
	);
`endif

`ifdef Z80_CHEAT
	reg [7:0] z80_data;
	always @(posedge clk_md) z80_data <= z80_genie_data;

	wire [7:0] z80_genie_data;
	CODES #(.ADDR_WIDTH(16), .DATA_WIDTH(8)) codes_z80
	(
		.clk(clk_sys),
